-- Placeholders like {{ run_id }} are filled in by the ELT DAG at run time.
-- Adds one f_<check> column per rule, plus dq_status, failure_reason, warning_reason
CREATE OR REPLACE TABLE stg_customers_flagged AS
SELECT *,
  CASE WHEN "f_customer_id_not_null" OR "f_customer_id_unique" THEN 'FAIL' WHEN "f_email_present" OR "f_city_present" OR "f_email_format" OR "f_phone_format" OR "f_customer_pincode_format" OR "f_loyalty_tier_allowed" OR "f_signup_date_valid" OR "f_loyalty_tier_standard" OR "f_customer_pincode_bengaluru" OR "f_signup_date_not_future" THEN 'WARN' ELSE 'PASS' END AS dq_status,
  NULLIF(concat_ws('; ', CASE WHEN "f_customer_id_not_null" THEN 'customer_id_not_null' END, CASE WHEN "f_customer_id_unique" THEN 'customer_id_unique' END), '') AS failure_reason,
  NULLIF(concat_ws('; ', CASE WHEN "f_email_present" THEN 'email_present' END, CASE WHEN "f_city_present" THEN 'city_present' END, CASE WHEN "f_email_format" THEN 'email_format' END, CASE WHEN "f_phone_format" THEN 'phone_format' END, CASE WHEN "f_customer_pincode_format" THEN 'customer_pincode_format' END, CASE WHEN "f_loyalty_tier_allowed" THEN 'loyalty_tier_allowed' END, CASE WHEN "f_signup_date_valid" THEN 'signup_date_valid' END, CASE WHEN "f_loyalty_tier_standard" THEN 'loyalty_tier_standard' END, CASE WHEN "f_customer_pincode_bengaluru" THEN 'customer_pincode_bengaluru' END, CASE WHEN "f_signup_date_not_future" THEN 'signup_date_not_future' END), '') AS warning_reason
FROM (
  SELECT t.*,
    COALESCE((t.customer_id IS NULL), FALSE) AS "f_customer_id_not_null",
    COALESCE((t.email IS NULL), FALSE) AS "f_email_present",
    COALESCE((t.city IS NULL), FALSE) AS "f_city_present",
    COALESCE((t.customer_id IS NOT NULL AND row_number() OVER (PARTITION BY t.customer_id ORDER BY t._row DESC) > 1), FALSE) AS "f_customer_id_unique",
    COALESCE((t.email IS NOT NULL AND NOT regexp_full_match(t.email, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')), FALSE) AS "f_email_format",
    COALESCE((t.phone IS NOT NULL AND NOT coalesce(regexp_full_match(t.phone_norm, '[6-9][0-9]{9}'), FALSE)), FALSE) AS "f_phone_format",
    COALESCE((t.pincode IS NOT NULL AND NOT regexp_full_match(t.pincode, '[0-9]{6}')), FALSE) AS "f_customer_pincode_format",
    COALESCE((t.loyalty_tier IS NULL), FALSE) AS "f_loyalty_tier_allowed",
    COALESCE((t.signup_date_raw IS NOT NULL AND t.signup_date IS NULL), FALSE) AS "f_signup_date_valid",
    COALESCE((t.loyalty_tier IS NOT NULL AND t.loyalty_tier_raw <> t.loyalty_tier), FALSE) AS "f_loyalty_tier_standard",
    COALESCE((regexp_full_match(t.pincode, '[0-9]{6}') AND t.pincode NOT LIKE '56%'), FALSE) AS "f_customer_pincode_bengaluru",
    COALESCE((t.signup_date >= TIMESTAMP '{{ next_day }}'), FALSE) AS "f_signup_date_not_future"
  FROM stg_customers_std t
) AS flagged;
